-- candidate_stages (pipeline tracking per candidate per job)
CREATE TABLE IF NOT EXISTS candidate_stages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resume_id uuid REFERENCES rankora_resumes(id) ON DELETE CASCADE,
  job_id uuid REFERENCES rankora_jobs(id) ON DELETE CASCADE,
  stage text NOT NULL DEFAULT 'new',
  moved_at timestamptz NOT NULL DEFAULT now(),
  moved_by uuid REFERENCES users(id),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_candidate_stages_resume ON candidate_stages(resume_id);
CREATE INDEX IF NOT EXISTS idx_candidate_stages_job ON candidate_stages(job_id);
ALTER TABLE candidate_stages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS candidate_stages_all ON candidate_stages;
CREATE POLICY candidate_stages_all ON candidate_stages FOR ALL TO authenticated USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON candidate_stages TO authenticated;

-- career_subscribers (email subscribers on career pages)
CREATE TABLE IF NOT EXISTS career_subscribers (
