DROP POLICY IF EXISTS career_subscribers_all ON career_subscribers;
CREATE POLICY career_subscribers_all ON career_subscribers FOR ALL USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, DELETE ON career_subscribers TO authenticated, anon;

