-- ============================================================================
-- 20260420000017_add_app_id_to_legacy_tables.sql
--
-- Adds app_id to all 34 legacy tables that were created before the BUBS
-- multi-app architecture. Backfills existing rows with the Rankora app UUID,
-- replaces weak/open RLS policies with proper is_account_member() +
-- has_app_access() checks matching the rankora_* table convention.
-- ============================================================================

-- ────────────────────────────────────────────────────────────────────────────
-- PART 1: Add app_id column + backfill + NOT NULL
-- ────────────────────────────────────────────────────────────────────────────

-- Helper: wrap repeated ALTER + UPDATE + SET NOT NULL in a DO block
-- so the migration is idempotent (safe to re-run if partially applied).

DO $add_app_id$
DECLARE
  v_app_id uuid := get_app_id('rankora');
  tbl text;
BEGIN
  IF v_app_id IS NULL THEN
    RAISE EXCEPTION 'Rankora app not found in apps table — cannot backfill app_id';
  END IF;

  -- ── Category 1: tables with account_id ──────────────────────────────────
  FOREACH tbl IN ARRAY ARRAY[
    'activity_log',
    'agency_clients',
    'agency_commissions',
    'agency_communications',
    'agency_contacts',
    'agency_invoices',
    'agency_mandates',
    'agency_placements',
    'availability_slots',
    'guest_links',
    'hire_outcomes',
    'interviews',
    'notifications',
    'outreach_history',
    'payments',
    'scorecard_responses',
    'scorecard_templates',
    'sequences',
    'stage_tracker',
    'talent_pool',
    'talent_pool_members',
    'team_invitations',
    'webhook_configs'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
    ) THEN
      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
    END IF;
  END LOOP;

  -- ── Category 2: tables connected via FK chain ───────────────────────────
  FOREACH tbl IN ARRAY ARRAY[
    'booking_tokens',
    'candidate_stages',
    'career_subscribers',
    'job_form_fields',
    'job_views',
    'outreach_log',
    'sequence_enrollments',
    'sequence_steps',
    'stage_automations',
    'stage_history',
    'sms_logs'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
    ) THEN
      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
    END IF;
  END LOOP;
END $add_app_id$;


