-- ============================================================================
-- 20260420000018_fix_app_id_defaults_and_triggers.sql
--
-- Fixes the INSERT failure on all 34 legacy tables from migration 0017.
-- Problem: app_id is NOT NULL but has no DEFAULT and no trigger — frontend
-- never passes app_id, so all INSERTs fail with "null value" constraint.
--
-- Solution:
-- 1. Add DEFAULT get_app_id('rankora') on app_id for all 34 tables
-- 2. Add BEFORE INSERT trigger as safety net (in case DEFAULT doesn't fire)
-- 3. Add app_id to the 2 remaining gap tables (rankora_platform_config,
--    email_ingest_logs)
-- ============================================================================


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1: Shared trigger function — auto-populates app_id on INSERT
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION set_rankora_app_id()
RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.app_id IS NULL THEN
    NEW.app_id := get_app_id('rankora');
  END IF;
  RETURN NEW;
END;
$$;


-- ────────────────────────────────────────────────────────────────────────────
-- PART 2: Add DEFAULT + BEFORE INSERT trigger on all 34 legacy tables
-- ────────────────────────────────────────────────────────────────────────────

-- Category 1: 23 tables with account_id
ALTER TABLE activity_log ALTER COLUMN app_id SET DEFAULT get_app_id('rankora');
CREATE TRIGGER trg_activity_log_app_id BEFORE INSERT ON activity_log
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

ALTER TABLE agency_clients ALTER COLUMN app_id SET DEFAULT get_app_id('rankora');
CREATE TRIGGER trg_agency_clients_app_id BEFORE INSERT ON agency_clients
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

ALTER TABLE agency_commissions ALTER COLUMN app_id SET DEFAULT get_app_id('rankora');
