CREATE TRIGGER trg_agency_contacts_app_id BEFORE INSERT ON agency_contacts
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

ALTER TABLE agency_invoices ALTER COLUMN app_id SET DEFAULT get_app_id('rankora');
CREATE TRIGGER trg_agency_invoices_app_id BEFORE INSERT ON agency_invoices
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

ALTER TABLE agency_mandates ALTER COLUMN app_id SET DEFAULT get_app_id('rankora');
