-- ============================================================================
-- 20260420000014_fix_security_definer_views.sql
-- Fix Supabase linter errors: convert all SECURITY DEFINER views to
-- SECURITY INVOKER so RLS policies of the querying user are enforced.
--
-- This is safe now because migrations 0011 and 0013 fixed:
--   - has_app_access() fallback for account owners
--   - Proper GRANTs on all underlying tables
--   - RLS policies that work for authenticated users
-- ============================================================================

-- profiles: stays as a function-backed view (get_user_profile is SECURITY
-- DEFINER by design — it only returns the caller's own row via auth.uid())
-- The VIEW itself just wraps the function, so set it to invoker.
DROP VIEW IF EXISTS profiles;
CREATE VIEW profiles WITH (security_invoker = true) AS
  SELECT * FROM get_user_profile();
GRANT SELECT ON profiles TO authenticated;

-- jobs
DROP VIEW IF EXISTS jobs CASCADE;
CREATE VIEW jobs WITH (security_invoker = true) AS
SELECT
  rj.id,
  a.owner_user_id AS user_id,
  rj.account_id AS team_id,
  rj.account_id,
  rj.app_id,
  rj.created_by,
  rj.title,
  rj.job_description,
  rj.jd_analysis_json,
  rj.dynamic_weights_json,
  rj.scoring_weights,
  rj.status,
  rj.inbox_email,
  rj.jd_embedding,
  rj.created_at,
  rj.updated_at
FROM rankora_jobs rj
JOIN accounts a ON a.id = rj.account_id;
GRANT SELECT, INSERT, UPDATE, DELETE ON jobs TO authenticated;
CREATE TRIGGER jobs_insert_instead_of INSTEAD OF INSERT ON jobs FOR EACH ROW EXECUTE FUNCTION jobs_insert_trigger();
CREATE TRIGGER jobs_update_instead_of INSTEAD OF UPDATE ON jobs FOR EACH ROW EXECUTE FUNCTION jobs_update_trigger();
CREATE TRIGGER jobs_delete_instead_of INSTEAD OF DELETE ON jobs FOR EACH ROW EXECUTE FUNCTION jobs_delete_trigger();

-- resumes
DROP VIEW IF EXISTS resumes CASCADE;
CREATE VIEW resumes WITH (security_invoker = true) AS
SELECT
  rr.id, rr.job_id,
  a.owner_user_id AS user_id,
  rr.account_id, rr.app_id, rr.created_by,
  rr.filename, rr.file_path, rr.file_size_bytes,
  rr.candidate_name, rr.candidate_email, rr.candidate_phone, rr.candidate_location,
  rr.parsed_json, rr.parsed_text, rr.embedding,
  rr.status, rr.source, rr.created_at
FROM rankora_resumes rr
JOIN accounts a ON a.id = rr.account_id;
GRANT SELECT, INSERT, UPDATE, DELETE ON resumes TO authenticated;
CREATE TRIGGER resumes_insert_instead_of INSTEAD OF INSERT ON resumes FOR EACH ROW EXECUTE FUNCTION resumes_insert_trigger();
CREATE TRIGGER resumes_update_instead_of INSTEAD OF UPDATE ON resumes FOR EACH ROW EXECUTE FUNCTION resumes_update_trigger();
CREATE TRIGGER resumes_delete_instead_of INSTEAD OF DELETE ON resumes FOR EACH ROW EXECUTE FUNCTION resumes_delete_trigger();

-- results
DROP VIEW IF EXISTS results CASCADE;
CREATE VIEW results WITH (security_invoker = true) AS
SELECT
  rr.id, rr.resume_id, rr.job_id,
  a.owner_user_id AS user_id,
  rr.account_id, rr.app_id,
  rr.overall_score, rr.skill_score, rr.experience_score, rr.education_score,
  rr.missing_skills, rr.strengths_json, rr.gaps_json,
  rr.explanation_json, rr.category_scores_json, rr.interview_questions,
  rr.matched_must_haves, rr.missing_must_haves,
  rr.confidence, rr.hard_fit, rr.created_at
FROM rankora_results rr
JOIN rankora_jobs rj ON rj.id = rr.job_id
JOIN accounts a ON a.id = rj.account_id;
GRANT SELECT, INSERT, UPDATE ON results TO authenticated;
CREATE TRIGGER results_insert_instead_of INSTEAD OF INSERT ON results FOR EACH ROW EXECUTE FUNCTION results_insert_trigger();
CREATE TRIGGER results_update_instead_of INSTEAD OF UPDATE ON results FOR EACH ROW EXECUTE FUNCTION results_update_trigger();

-- user_roles
DROP VIEW IF EXISTS user_roles CASCADE;
CREATE VIEW user_roles WITH (security_invoker = true) AS
SELECT
  u.id AS user_id,
  CASE
    WHEN u.email = 'boldteq@gmail.com' THEN 'admin'
    WHEN u.email LIKE '%@boldteq.com' THEN 'admin'
    WHEN u.email LIKE '%@rankora.co' THEN 'admin'
    ELSE 'user'
  END AS role
FROM users u;
GRANT SELECT ON user_roles TO authenticated;

-- Recreate auth_page_config admin policy (depends on user_roles view)
DROP POLICY IF EXISTS auth_page_config_admin_write ON auth_page_config;
CREATE POLICY auth_page_config_admin_write ON auth_page_config FOR ALL
  USING (EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'admin'));

-- platform_config
DROP VIEW IF EXISTS platform_config CASCADE;
CREATE VIEW platform_config WITH (security_invoker = true) AS
SELECT
  rpc.account_id AS id,
  rpc.account_id,
  rpc.max_resumes_per_job,
  rpc.max_file_size_mb,
  rpc.resume_retention_days,
  rpc.email_ingestion_enabled,
  rpc.auto_rank_enabled,
  rpc.updated_at
FROM rankora_platform_config rpc;
GRANT SELECT, UPDATE ON platform_config TO authenticated;

-- feature_flags
DROP VIEW IF EXISTS feature_flags CASCADE;
CREATE VIEW feature_flags WITH (security_invoker = true) AS
SELECT
  ff.id,
  ff.flag_key AS key,
  ff.flag_key AS name,
  ff.description,
  ff.enabled,
  ff.value_json,
  ff.created_at,
  ff.updated_at
FROM rankora_feature_flags ff
WHERE ff.account_id IS NULL
   OR ff.account_id = get_primary_account(auth.uid());
GRANT SELECT ON feature_flags TO authenticated;

-- pipeline_stages
DROP VIEW IF EXISTS pipeline_stages CASCADE;
CREATE VIEW pipeline_stages WITH (security_invoker = true) AS
SELECT * FROM job_pipeline_stages;
GRANT SELECT, INSERT, UPDATE, DELETE ON pipeline_stages TO authenticated;

-- Analytics views
DROP VIEW IF EXISTS v_daily_activity CASCADE;
CREATE VIEW v_daily_activity WITH (security_invoker = true) AS
SELECT date_trunc('day', al.created_at)::date AS day, al.action, count(*) AS count
FROM activity_log al GROUP BY 1, 2;
GRANT SELECT ON v_daily_activity TO authenticated;

DROP VIEW IF EXISTS v_score_distribution CASCADE;
CREATE VIEW v_score_distribution WITH (security_invoker = true) AS
SELECT rr.job_id, width_bucket(rr.overall_score::numeric, 0, 100, 10) AS bucket, count(*) AS count
FROM rankora_results rr WHERE rr.overall_score IS NOT NULL GROUP BY 1, 2;
GRANT SELECT ON v_score_distribution TO authenticated;

DROP VIEW IF EXISTS v_stage_conversion CASCADE;
CREATE VIEW v_stage_conversion WITH (security_invoker = true) AS
SELECT sh.job_id, sh.from_stage, sh.to_stage, count(*) AS count
FROM stage_history sh GROUP BY 1, 2, 3;
GRANT SELECT ON v_stage_conversion TO authenticated;

DROP VIEW IF EXISTS v_time_to_hire CASCADE;
CREATE VIEW v_time_to_hire WITH (security_invoker = true) AS
SELECT ho.job_id, avg(extract(epoch FROM ho.created_at - rj.created_at) / 86400)::numeric(10,1) AS avg_days
FROM hire_outcomes ho JOIN rankora_jobs rj ON rj.id = ho.job_id GROUP BY 1;
GRANT SELECT ON v_time_to_hire TO authenticated;

DROP VIEW IF EXISTS v_top_jobs CASCADE;
CREATE VIEW v_top_jobs WITH (security_invoker = true) AS
SELECT rj.id AS job_id, rj.title, count(rr.id) AS resume_count,
  COALESCE(avg(res.overall_score)::numeric(5,1), 0) AS avg_score, rj.created_at
FROM rankora_jobs rj
LEFT JOIN rankora_resumes rr ON rr.job_id = rj.id
LEFT JOIN rankora_results res ON res.job_id = rj.id AND res.resume_id = rr.id
GROUP BY rj.id, rj.title, rj.created_at ORDER BY resume_count DESC;
GRANT SELECT ON v_top_jobs TO authenticated;

