type SlugStatus = "idle" | "checking" | "available" | "taken";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

// ---------------------------------------------------------------------------
// Skeleton components
// ---------------------------------------------------------------------------

function ConfigSkeleton() {
  return (
    <div className="space-y-5">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div key={i} className="space-y-1.5">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-9 w-full" />
        </div>
      ))}
      <Skeleton className="h-9 w-28 mt-2" />
    </div>
  );
}

function JobsSkeleton() {
  return (
    <div className="space-y-0">
      {[1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
          <Skeleton className="h-4 flex-1" />
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-5 w-10 rounded-full" />
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Slug status indicator
// ---------------------------------------------------------------------------

function SlugStatusBadge({ status }: { status: SlugStatus }) {
  if (status === "idle") return null;
  if (status === "checking") {
    return (
      <span className="flex items-center gap-1 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Checking…
      </span>
    );
  }
  if (status === "available") {
    return (
      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
        Available
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
      Already taken
    </Badge>
  );
}

