-- ============================================================================
-- 20260420000019_fix_missing_triggers_and_column_maps.sql
--
-- Comprehensive fix for all views that grant INSERT/UPDATE/DELETE but have
-- no INSTEAD OF triggers (all writes silently fail), plus view/table column
-- mismatches that break frontend reads.
--
-- Changes:
--  1. Fix platform_config view — restore per-account WHERE filter
--  2. Add results DELETE trigger
--  3. Rebuild job_pipeline_stages + pipeline_stages with sort_order alias
--  4. Add INSTEAD OF triggers: tasks, candidate_notes, candidate_tags,
--     career_page_config, feature_requests, applications, api_keys,
--     team_members, teams, job_pipeline_stages, pipeline_stages
--  5. Add missing columns: rankora_applications, rankora_feature_requests,
--     outreach_log, sms_logs, scorecard_responses
--  6. Fix applications view to expose expected column aliases
-- ============================================================================


-- ────────────────────────────────────────────────────────────────────────────
-- PART 1: Fix platform_config view (restore per-account WHERE filter)
-- Migration 0014 dropped it, causing all accounts' config to be returned
-- ────────────────────────────────────────────────────────────────────────────

DROP VIEW IF EXISTS platform_config CASCADE;
CREATE VIEW platform_config WITH (security_invoker = true) AS
SELECT
  rpc.account_id AS id,
  rpc.account_id,
  rpc.max_resumes_per_job,
  rpc.max_file_size_mb,
  rpc.resume_retention_days,
  rpc.email_ingestion_enabled,
  rpc.auto_rank_enabled,
  rpc.updated_at
FROM rankora_platform_config rpc
WHERE rpc.account_id = get_primary_account(auth.uid());
GRANT SELECT, UPDATE ON platform_config TO authenticated;

CREATE OR REPLACE FUNCTION platform_config_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_platform_config SET
    max_resumes_per_job     = NEW.max_resumes_per_job,
    max_file_size_mb        = NEW.max_file_size_mb,
    resume_retention_days   = NEW.resume_retention_days,
    email_ingestion_enabled = NEW.email_ingestion_enabled,
    auto_rank_enabled       = NEW.auto_rank_enabled
  WHERE account_id = OLD.account_id;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS platform_config_update_instead_of ON platform_config;
CREATE TRIGGER platform_config_update_instead_of
  INSTEAD OF UPDATE ON platform_config
  FOR EACH ROW EXECUTE FUNCTION platform_config_update_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 2: results DELETE trigger (INSERT + UPDATE already exist from 0014)
-- ────────────────────────────────────────────────────────────────────────────

GRANT DELETE ON results TO authenticated;

CREATE OR REPLACE FUNCTION results_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  DELETE FROM rankora_results WHERE id = OLD.id;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS results_delete_instead_of ON results;
CREATE TRIGGER results_delete_instead_of
  INSTEAD OF DELETE ON results
  FOR EACH ROW EXECUTE FUNCTION results_delete_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 3: Rebuild job_pipeline_stages + pipeline_stages with sort_order alias
-- Frontend uses sort_order but the base table has position
-- ────────────────────────────────────────────────────────────────────────────

DROP VIEW IF EXISTS pipeline_stages CASCADE;
DROP VIEW IF EXISTS job_pipeline_stages CASCADE;

CREATE VIEW job_pipeline_stages WITH (security_invoker = true) AS
SELECT
  id,
  account_id AS team_id,
  account_id,
  name,
  slug,
  color,
  position,
  position AS sort_order,
  is_default,
  created_at,
  updated_at
FROM rankora_pipeline_stages;
GRANT SELECT, INSERT, UPDATE, DELETE ON job_pipeline_stages TO authenticated;

CREATE VIEW pipeline_stages WITH (security_invoker = true) AS
SELECT * FROM job_pipeline_stages;
GRANT SELECT, INSERT, UPDATE, DELETE ON pipeline_stages TO authenticated;

-- Shared trigger functions for both views
CREATE OR REPLACE FUNCTION pipeline_stages_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_pipeline_stages (
    id, app_id, account_id, name, slug, color, position, is_default
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    NEW.name,
    COALESCE(NEW.slug, lower(regexp_replace(NEW.name, '[^a-zA-Z0-9]', '-', 'g'))),
    COALESCE(NEW.color, '#6b7280'),
    COALESCE(NEW.position, NEW.sort_order, 0),
    COALESCE(NEW.is_default, false)
  );
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION pipeline_stages_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_pipeline_stages SET
    name      = COALESCE(NEW.name, name),
    color     = COALESCE(NEW.color, color),
    position  = COALESCE(NEW.position, NEW.sort_order, position),
    is_default = COALESCE(NEW.is_default, is_default)
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION pipeline_stages_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  DELETE FROM rankora_pipeline_stages WHERE id = OLD.id;
  RETURN OLD;
END;
$$;

-- Triggers on job_pipeline_stages
DROP TRIGGER IF EXISTS job_pipeline_stages_insert_instead_of ON job_pipeline_stages;
CREATE TRIGGER job_pipeline_stages_insert_instead_of
  INSTEAD OF INSERT ON job_pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_insert_trigger();

DROP TRIGGER IF EXISTS job_pipeline_stages_update_instead_of ON job_pipeline_stages;
CREATE TRIGGER job_pipeline_stages_update_instead_of
  INSTEAD OF UPDATE ON job_pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_update_trigger();

DROP TRIGGER IF EXISTS job_pipeline_stages_delete_instead_of ON job_pipeline_stages;
CREATE TRIGGER job_pipeline_stages_delete_instead_of
  INSTEAD OF DELETE ON job_pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_delete_trigger();

-- Triggers on pipeline_stages (passthrough to rankora_pipeline_stages)
DROP TRIGGER IF EXISTS pipeline_stages_insert_instead_of ON pipeline_stages;
CREATE TRIGGER pipeline_stages_insert_instead_of
  INSTEAD OF INSERT ON pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_insert_trigger();

DROP TRIGGER IF EXISTS pipeline_stages_update_instead_of ON pipeline_stages;
CREATE TRIGGER pipeline_stages_update_instead_of
  INSTEAD OF UPDATE ON pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_update_trigger();

DROP TRIGGER IF EXISTS pipeline_stages_delete_instead_of ON pipeline_stages;
CREATE TRIGGER pipeline_stages_delete_instead_of
  INSTEAD OF DELETE ON pipeline_stages
  FOR EACH ROW EXECUTE FUNCTION pipeline_stages_delete_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 4: tasks INSTEAD OF triggers → rankora_tasks
-- View columns: id, user_id(=account_id), team_id(=account_id), account_id,
--   created_by, assigned_to(=assignee_user_id), title, description, due_date,
--   status, priority, related_entity_type, related_entity_id, completed_at,
--   created_at, updated_at
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION tasks_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, NEW.user_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_tasks (
    id, app_id, account_id, created_by, assignee_user_id,
    title, description, due_date, status, priority,
    related_entity_type, related_entity_id, completed_at
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    COALESCE(NEW.created_by, auth.uid()),
    NEW.assigned_to,
    NEW.title,
    NEW.description,
    NEW.due_date,
    COALESCE(NEW.status, 'pending'),
    COALESCE(NEW.priority, 'medium'),
    NEW.related_entity_type,
    NEW.related_entity_id,
    NEW.completed_at
  );
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION tasks_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_tasks SET
    assignee_user_id    = NEW.assigned_to,
    title               = COALESCE(NEW.title, title),
    description         = NEW.description,
    due_date            = NEW.due_date,
    status              = COALESCE(NEW.status, status),
    priority            = COALESCE(NEW.priority, priority),
    related_entity_type = NEW.related_entity_type,
    related_entity_id   = NEW.related_entity_id,
    completed_at        = NEW.completed_at
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION tasks_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  DELETE FROM rankora_tasks WHERE id = OLD.id;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS tasks_insert_instead_of ON tasks;
CREATE TRIGGER tasks_insert_instead_of
  INSTEAD OF INSERT ON tasks
  FOR EACH ROW EXECUTE FUNCTION tasks_insert_trigger();

DROP TRIGGER IF EXISTS tasks_update_instead_of ON tasks;
CREATE TRIGGER tasks_update_instead_of
  INSTEAD OF UPDATE ON tasks
  FOR EACH ROW EXECUTE FUNCTION tasks_update_trigger();

DROP TRIGGER IF EXISTS tasks_delete_instead_of ON tasks;
CREATE TRIGGER tasks_delete_instead_of
  INSTEAD OF DELETE ON tasks
  FOR EACH ROW EXECUTE FUNCTION tasks_delete_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 5: candidate_notes INSTEAD OF triggers → rankora_candidate_notes
-- View columns: id, user_id(=account_id), team_id(=account_id), account_id,
--   resume_id, created_by, content(=body), body, created_at, updated_at
-- NOTE: frontend passes author_id/note_type/mentions — these are not view
--       columns so Supabase ignores them; trigger uses auth.uid() for created_by
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION candidate_notes_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_candidate_notes (
    id, app_id, account_id, resume_id, created_by, body
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    NEW.resume_id,
    COALESCE(NEW.created_by, auth.uid()),
    COALESCE(NEW.body, NEW.content)
  );
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION candidate_notes_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_candidate_notes SET
    body = COALESCE(NEW.body, NEW.content, body)
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION candidate_notes_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  DELETE FROM rankora_candidate_notes WHERE id = OLD.id;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS candidate_notes_insert_instead_of ON candidate_notes;
CREATE TRIGGER candidate_notes_insert_instead_of
  INSTEAD OF INSERT ON candidate_notes
  FOR EACH ROW EXECUTE FUNCTION candidate_notes_insert_trigger();

DROP TRIGGER IF EXISTS candidate_notes_update_instead_of ON candidate_notes;
CREATE TRIGGER candidate_notes_update_instead_of
  INSTEAD OF UPDATE ON candidate_notes
  FOR EACH ROW EXECUTE FUNCTION candidate_notes_update_trigger();

DROP TRIGGER IF EXISTS candidate_notes_delete_instead_of ON candidate_notes;
CREATE TRIGGER candidate_notes_delete_instead_of
  INSTEAD OF DELETE ON candidate_notes
  FOR EACH ROW EXECUTE FUNCTION candidate_notes_delete_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 6: candidate_tags INSTEAD OF triggers → rankora_candidate_tags
-- View columns: id, user_id(=account_id), team_id(=account_id), account_id,
--   resume_id, created_by, tag, color, created_at
-- NOTE: frontend passes job_id — not a view column, Supabase ignores it
-- ────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION candidate_tags_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_candidate_tags (
    id, app_id, account_id, resume_id, created_by, tag, color
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    NEW.resume_id,
    COALESCE(NEW.created_by, auth.uid()),
    NEW.tag,
    COALESCE(NEW.color, '#6366f1')
  );
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION candidate_tags_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_candidate_tags SET
    tag   = COALESCE(NEW.tag, tag),
    color = COALESCE(NEW.color, color)
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION candidate_tags_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  DELETE FROM rankora_candidate_tags WHERE id = OLD.id;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS candidate_tags_insert_instead_of ON candidate_tags;
CREATE TRIGGER candidate_tags_insert_instead_of
  INSTEAD OF INSERT ON candidate_tags
  FOR EACH ROW EXECUTE FUNCTION candidate_tags_insert_trigger();

DROP TRIGGER IF EXISTS candidate_tags_update_instead_of ON candidate_tags;
CREATE TRIGGER candidate_tags_update_instead_of
  INSTEAD OF UPDATE ON candidate_tags
  FOR EACH ROW EXECUTE FUNCTION candidate_tags_update_trigger();

DROP TRIGGER IF EXISTS candidate_tags_delete_instead_of ON candidate_tags;
CREATE TRIGGER candidate_tags_delete_instead_of
  INSTEAD OF DELETE ON candidate_tags
  FOR EACH ROW EXECUTE FUNCTION candidate_tags_delete_trigger();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 7: career_page_config INSTEAD OF triggers → rankora_career_pages
-- View columns: id, user_id(=account_id), team_id(=account_id), account_id,
