CREATE OR REPLACE FUNCTION career_page_config_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, NEW.user_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_career_pages (
    id, app_id, account_id, slug, company_name, logo_url, cover_image_url,
    brand_color, tagline, about, culture_title, culture_description,
    benefits_json, testimonials_json, social_links_json,
    meta_title, meta_description, is_published
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    NEW.slug,
    NEW.company_name,
    NEW.logo_url,
    NEW.cover_image_url,
    COALESCE(NEW.brand_color, '#6366f1'),
    NEW.tagline,
    NEW.about,
    NEW.culture_title,
    NEW.culture_description,
    NEW.benefits_json,
    NEW.testimonials_json,
    NEW.social_links_json,
    NEW.meta_title,
    NEW.meta_description,
    COALESCE(NEW.is_published, false)
  );
  RETURN NEW;
END;
$$;

