-- Backfill evaluator_id from reviewer_id for existing rows
UPDATE scorecard_responses SET evaluator_id = reviewer_id WHERE evaluator_id IS NULL AND reviewer_id IS NOT NULL;

-- Unique constraint for the upsert used in useSubmitScorecardResponse
DO $$ BEGIN
