-- PART 9: Add missing columns to rankora_applications, then rebuild view
-- Frontend expects: name, email, phone, linkedin_url, resume_filename,
--   auto_disqualified, disqualify_reason, custom_fields
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE rankora_applications ADD COLUMN IF NOT EXISTS linkedin_url text;
ALTER TABLE rankora_applications ADD COLUMN IF NOT EXISTS resume_filename text;
ALTER TABLE rankora_applications ADD COLUMN IF NOT EXISTS auto_disqualified boolean DEFAULT false;
ALTER TABLE rankora_applications ADD COLUMN IF NOT EXISTS disqualify_reason text;

-- Recreate applications view with proper column aliases
DROP VIEW IF EXISTS applications CASCADE;
CREATE VIEW applications WITH (security_invoker = true) AS
SELECT
  id,
  account_id AS user_id,
  account_id AS team_id,
  account_id,
  job_id,
  candidate_name,
  candidate_name   AS name,
  candidate_email,
  candidate_email  AS email,
  candidate_phone,
  candidate_phone  AS phone,
  linkedin_url,
  resume_path,
  resume_filename,
  custom_fields_json,
  custom_fields_json AS custom_fields,
  source,
  status,
  auto_disqualified,
  disqualify_reason,
  created_at,
  updated_at
FROM rankora_applications;
GRANT SELECT, INSERT, UPDATE, DELETE ON applications TO authenticated, anon;

CREATE OR REPLACE FUNCTION applications_insert_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, NEW.user_id,
    (SELECT account_id FROM rankora_jobs WHERE id = NEW.job_id),
    get_primary_account(auth.uid()));
  INSERT INTO rankora_applications (
    id, app_id, account_id, job_id,
    candidate_name, candidate_email, candidate_phone,
    linkedin_url, resume_path, resume_filename,
    custom_fields_json, source, status,
    auto_disqualified, disqualify_reason
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    NEW.job_id,
    COALESCE(NEW.candidate_name, NEW.name),
    COALESCE(NEW.candidate_email, NEW.email),
    COALESCE(NEW.candidate_phone, NEW.phone),
    NEW.linkedin_url,
    NEW.resume_path,
    NEW.resume_filename,
    COALESCE(NEW.custom_fields_json, NEW.custom_fields),
    NEW.source,
    COALESCE(NEW.status, 'new'),
    COALESCE(NEW.auto_disqualified, false),
    NEW.disqualify_reason
  );
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION applications_update_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  UPDATE rankora_applications SET
    status            = COALESCE(NEW.status, status),
    candidate_name    = COALESCE(NEW.candidate_name, NEW.name, candidate_name),
    candidate_email   = COALESCE(NEW.candidate_email, NEW.email, candidate_email),
    candidate_phone   = COALESCE(NEW.candidate_phone, NEW.phone, candidate_phone),
    linkedin_url      = COALESCE(NEW.linkedin_url, linkedin_url),
    custom_fields_json = COALESCE(NEW.custom_fields_json, NEW.custom_fields, custom_fields_json),
    auto_disqualified = COALESCE(NEW.auto_disqualified, auto_disqualified),
    disqualify_reason = COALESCE(NEW.disqualify_reason, disqualify_reason)
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

