function normalizeStatus(raw: string | null | undefined): OutreachStatus {
  if (raw === "failed") return "failed";
  if (raw === "pending") return "pending";
  return "sent";
}

function fromOutreachLog(row: OutreachLogRow): OutreachEvent {
  return {
    id: `email:${row.id}`,
    kind: "email",
    to: row.to_address ?? "",
    subject: row.subject ?? null,
    body: null,
    status: normalizeStatus(row.status),
    sent_at: row.sent_at ?? new Date(0).toISOString(),
    sender_user_id: row.user_id ?? null,
    error: null,
  };
}

function fromSmsLog(row: SmsLogRow): OutreachEvent {
  return {
    id: `sms:${row.id}`,
    kind: "sms",
    to: row.to_phone,
    subject: null,
    body: row.message ?? null,
    status: normalizeStatus(row.status),
    sent_at: row.created_at ?? new Date(0).toISOString(),
    sender_user_id: row.user_id ?? null,
    error: row.error ?? null,
  };
}

