"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface AgencyPlacement {
  id: string;
  mandate_id: string;
  client_id: string;
  candidate_name: string;
  candidate_email: string | null;
  status: "offered" | "accepted" | "started" | "guarantee" | "completed" | "fallen_off";
  start_date: string | null;
  salary: number | null;
  fee_amount: number | null;
  guarantee_days: number | null;
  guarantee_expires_at: string | null;
  created_at: string;
  // Joined
  client_name?: string;
  mandate_title?: string;
}

export type CreatePlacementInput = Omit<AgencyPlacement, "id" | "created_at" | "client_name" | "mandate_title">;
export type UpdatePlacementInput = Partial<CreatePlacementInput> & { id: string };

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useAgencyPlacements(teamId: string | null) {
  const queryClient = useQueryClient();
  const queryKey = ["agency_placements", teamId];

  const { data, isLoading, error } = useQuery({
    queryKey,
    queryFn: async (): Promise<AgencyPlacement[]> => {
      if (!teamId) return [];
      try {
        const { data, error } = await (supabase as any)
          .from("agency_placements")
          .select("*, agency_clients(name), agency_mandates(job_title)")
          .eq("team_id", teamId)
          .order("created_at", { ascending: false });

        if (error) throw error;

        return ((data ?? []) as any[]).map((row) => ({
          ...row,
          client_name: row.agency_clients?.name ?? null,
          mandate_title: row.agency_mandates?.job_title ?? null,
          agency_clients: undefined,
          agency_mandates: undefined,
        })) as AgencyPlacement[];
      } catch (err) {
        console.error("useAgencyPlacements error:", err);
        return [];
      }
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  const createPlacement = useMutation({
    mutationFn: async (input: CreatePlacementInput) => {
      const { data, error } = await (supabase as any)
        .from("agency_placements")
        .insert(input)
        .select()
        .single();
      if (error) throw error;
      return data as AgencyPlacement;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Placement recorded");
    },
    onError: (err: Error) => {
      toast.error(`Failed to record placement: ${err.message}`);
    },
  });

  const updatePlacement = useMutation({
    mutationFn: async ({ id, ...updates }: UpdatePlacementInput) => {
      const { data, error } = await (supabase as any)
        .from("agency_placements")
        .update(updates)
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data as AgencyPlacement;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Placement updated");
    },
    onError: (err: Error) => {
      toast.error(`Failed to update placement: ${err.message}`);
    },
  });

  return {
    placements: data ?? [],
    isLoading,
    error,
    createPlacement,
    updatePlacement,
  };
}

