  // Callback-based items (dashboard/my-jobs use parent callbacks for internal view state)
  const callbackItems: NavCallbackItem[] = [
    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard!, show: isAuthenticated && !!onDashboard },
    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs!, show: isAuthenticated && !!onMyJobs },
  ];

  // Link-based items (use <Link> for prefetching + instant navigation)
  const mainLinks: NavLinkItem[] = [
    { icon: Bookmark, label: "Talent Pool", href: "/talent-pool", show: isAuthenticated },
    { icon: CheckSquare, label: "Tasks", href: "/tasks", show: isAuthenticated },
    { icon: Mail, label: "Sequences", href: "/sequences", show: isAuthenticated },
    { icon: BarChart3, label: "Reports", href: "/reports", show: isAuthenticated },
  ];

  const orgLinks: NavLinkItem[] = [
    { icon: Users, label: "Team Hub", href: "/team" },
    { icon: Building2, label: "Agency Hub", href: "/agency" },
    { icon: Globe, label: "Career Page", href: "/career-settings" },
    { icon: Plug, label: "Integrations", href: "/integrations" },
    { icon: CreditCard, label: "Billing", href: "/billing" },
    { icon: Settings, label: "Settings", href: "/settings" },
  ];

  const supportLinks: NavLinkItem[] = [
    { icon: Megaphone, label: "Feature Request", href: "/request-feature" },
    { icon: FileText, label: "Changelog", href: "/changelog" },
  ];

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      {/* Brand — fixed h-14 + mt-2 aligns with the right-pane AppHeader
          (which sits 8px below the viewport top due to the content card's
          p-2 wrapper). Same baseline in both expanded and collapsed modes. */}
      <SidebarHeader className="!flex !flex-row !gap-0 !p-0 h-14 mt-2 justify-start items-center px-4 group-data-[collapsible=icon]:px-0 group-data-[collapsible=icon]:justify-center">
        <div className="flex items-center gap-2">
          {appLogo ? (
            <img src={appLogo} alt={appName} className="h-5 w-5 shrink-0 object-contain" />
          ) : (
            <Layers className="h-5 w-5 text-primary shrink-0" />
          )}
          <span className="font-bold text-foreground tracking-tight text-base group-data-[collapsible=icon]:hidden">{appName}</span>
        </div>
      </SidebarHeader>

      {/* Navigation — px-2.5 in collapsed mode centers the 36x36 icon
          buttons inside the 56px sidebar column ((56-36)/2 = 10px each side). */}
      <SidebarContent className="px-2 py-1 group-data-[collapsible=icon]:px-2.5">
        <SectionLabel>Main</SectionLabel>
        <SidebarMenu>
          {/* Callback items (Dashboard, My Jobs — parent manages view state) */}
          {callbackItems
            .filter((i) => i.show !== false)
            .map((item) => (
              <SidebarMenuItem key={item.label}>
                <SidebarMenuButton
                  isActive={item.isActive}
                  onClick={item.onClick}
                  tooltip={item.label}
                  className={cn(
                    "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
                    item.isActive
                      ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
                      : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60",
                  )}
                >
                  <item.icon className={iconClass(item.isActive)} />
                  <span>{item.label}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ))}

          {/* Link items (prefetched, instant navigation) */}
          {mainLinks
            .filter((i) => i.show !== false)
            .map((item) => {
              const isActive = pathname === item.href;
              return (
                <SidebarMenuItem key={item.label}>
                  <Link href={item.href} prefetch className={navLinkClass(isActive)}>
                    <item.icon className={iconClass(isActive)} />
                    <span className="group-data-[collapsible=icon]:hidden">{item.label}</span>
                  </Link>
                </SidebarMenuItem>
              );
            })}
        </SidebarMenu>

        {isAuthenticated && (
          <>
            <SectionLabel>Organization</SectionLabel>
            <SidebarMenu>
              {orgLinks.map((item) => {
                const isActive = pathname === item.href;
                return (
                  <SidebarMenuItem key={item.label}>
                    <Link href={item.href} prefetch className={navLinkClass(isActive)}>
                      <item.icon className={iconClass(isActive)} />
                      <span className="group-data-[collapsible=icon]:hidden">{item.label}</span>
                    </Link>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </>
        )}

        <SectionLabel>Support</SectionLabel>
        <SidebarMenu>
          {supportLinks.map((item) => {
            const isActive = pathname === item.href;
            return (
              <SidebarMenuItem key={item.label}>
                <Link href={item.href} prefetch className={navLinkClass(isActive)}>
                  <item.icon className={iconClass(isActive)} />
                  <span className="group-data-[collapsible=icon]:hidden">{item.label}</span>
                </Link>
              </SidebarMenuItem>
            );
          })}
        </SidebarMenu>
      </SidebarContent>
    </Sidebar>
  );
};

export default JobSidebar;

