"use client";

import { useRouter, usePathname } from "next/navigation";
import { useAuth } from "@/hooks/useAuth";
import AppHeader from "@/components/AppHeader";
import JobSidebar from "@/components/JobSidebar";
import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";

/**
 * Shared layout with persistent JobSidebar + AppHeader.
 * Used by all authenticated pages (Settings, Billing, Admin, etc.).
 *
 * `defaultOpen` comes from the server-read `sidebar:state` cookie via
 * app/(app)/layout.tsx so the initial paint matches the user's last
 * toggle — prevents the expanded→collapsed flash on refresh.
 */
const SidebarLayout = ({
  children,
  defaultOpen = true,
}: {
  children: React.ReactNode;
  defaultOpen?: boolean;
}) => {
  const { user } = useAuth();
  const router = useRouter();
  const pathname = usePathname() ?? "/";

  // Both "/" and "/jobs" render the same <Index/> component. The sidebar
  // callback items (Dashboard / My Jobs) need active highlighting derived
  // from the current pathname since they don't have their own URLs in
  // the routes table — they're internal view toggles inside Index.tsx.
  const showDashboard = pathname === "/";
  const showMyJobs = pathname === "/jobs" || pathname.startsWith("/jobs/");

  return (
    <SidebarProvider defaultOpen={defaultOpen} className="h-svh overflow-hidden">
      <JobSidebar
        showDashboard={showDashboard}
        showMyJobs={showMyJobs}
        onNewJob={() => router.push("/?new=1")}
        onDashboard={() => router.push("/")}
        onMyJobs={() => router.push("/jobs")}
        onAuthRequired={() => router.push("/auth")}
        isAuthenticated={!!user}
      />
      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
          <AppHeader />
          <div className="flex items-center h-10 px-4 md:hidden">
            <SidebarTrigger />
          </div>
          <div className="flex-1 overflow-y-auto">
            {children}
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
};

export default SidebarLayout;

